struct ToolbarTelemetry {
    let gleanWrapper: GleanWrapper

    init(gleanWrapper: GleanWrapper = DefaultGleanWrapper()) {
        self.gleanWrapper = gleanWrapper
    }

@MainActor
private func cancelEditMode(windowUUID: WindowUUID) {
    var url = tabManager(for: windowUUID).selectedTab?.url
    if let currentURL = url {
        url = (currentURL.isWebPage() || currentURL.isReaderModeURL) ? url : nil
    }

private func recordReaderModeTelemetry(state: AppState, windowUUID: WindowUUID) {
    guard let toolbarState = state.screenState(ToolbarState.self, for: .toolbar, window: windowUUID) else { return }

    let isReaderModeEnabled = switch toolbarState.addressToolbar.readerModeState {
    case .available: false // will be enabled after action gets executed
    default: true
    }

    toolbarTelemetry.readerModeButtonTapped(isPrivate: toolbarState.isPrivateMode, isEnabled: isReaderModeEnabled)
}

@MainActor
private static func handleShowReaderModeAction(state: BrowserViewControllerState,
                                               action: GeneralBrowserAction) -> BrowserViewControllerState {
    return BrowserViewControllerState(
        searchScreenState: state.searchScreenState,
        toast: state.toast,
        windowUUID: state.windowUUID,
        browserViewType: state.browserViewType,
        displayView: .readerModeLongPressAction,
        microsurveyState: MicrosurveyPromptState.reducer(state.microsurveyState, action))
}

findings.body:
The `showReaderMode` reducer used to set `displayView: .readerMode`. This head sets `.readerModeLongPressAction` instead. `handleDisplayActions` maps `.readerMode` to `toggleReaderMode()` and `.readerModeLongPressAction` to `toggleReaderModeLongPressAction()`, which calls `profile.readingList.createRecordWithURL`. So the reader-mode toolbar button (the `ToolbarMiddleware` `.readerMode` tap dispatches `showReaderMode`) and the accessibility magic tap (`BrowserViewController.accessibilityPerformMagicTap` dispatches `showReaderMode`) now add the page to the reading list and never enable or disable reader mode.

::diff{file="firefox-ios/Client/Frontend/Browser/BrowserViewController/State/BrowserViewControllerState.swift" lines="559-568"}

::callout{type="warning"}
The PR description only mentions removing QR code code, so this change is unintentional. `.readerMode` is still a valid case and still handled in `handleDisplayActions`, so restoring it is a one-line fix.

::callout{type="warning"}

In `recordReaderModeTelemetry`, the `.available` case now returns `false`, and `default` returns `true`. The comment on the line says "will be enabled after action gets executed", which means `.available` should report `isEnabled: true`. As written, tapping to turn reader mode on logs `isEnabled: false`, and tapping to turn it off logs `isEnabled: true`. The inversion is also unrelated to the QR removal.

::code{file="firefox-ios/Client/Frontend/Browser/Toolbars/Redux/ToolbarMiddleware.swift" lines="521-528"}

::suggestion{file="firefox-ios/Client/Frontend/Browser/Toolbars/Redux/ToolbarMiddleware.swift" lines="524-525"}
case .available: true // will be enabled after action gets executed
default: false

`cancelEditMode` used to keep the selected tab's URL only if it was a web page and not a reader-mode URL. The head keeps it if it is a web page or a reader-mode URL. This changes what the address bar shows after cancelling edit for reader-mode tabs, and the PR description does not mention it. It isn't covered by any test in this diff.

::diff{file="firefox-ios/Client/Frontend/Browser/Toolbars/Redux/ToolbarMiddleware.swift" lines="482-490"}

If this is an intentional fix, it should be a separate PR with its own description and a test. Otherwise it should be reverted.
